"""matplotlib.units — unit conversion stubs."""

import numpy as _np


class ConversionError(TypeError):
    pass


class AxisInfo:
    def __init__(self, majloc=None, minloc=None, majfmt=None, minfmt=None,
                 label=None, default_limits=None):
        self.majloc = majloc
        self.minloc = minloc
        self.majfmt = majfmt
        self.minfmt = minfmt
        self.label = label
        self.default_limits = default_limits


class ConversionInterface:
    @staticmethod
    def axisinfo(unit, axis):
        return None

    @staticmethod
    def default_units(x, axis):
        return None

    @staticmethod
    def convert(obj, unit, axis):
        return _np.asarray(obj)


class DecimalConverter(ConversionInterface):
    pass


registry = {}


# ─── Added: missing public names from upstream units.py ────────────


class Registry(dict):
    """Mapping from a *unit type* (e.g. ``datetime.date`` or a custom
    class) to a :class:`ConversionInterface` subclass. Upstream uses
    this to find the converter for a given data type — the shim
    behaves the same way; we just subclass ``dict`` for the same API.

    The lookup walks the MRO of the data's type to find the *first*
    registered converter that handles a base class.
    """

    def get_converter(self, x):
        """Find the registered converter for ``x``. Returns ``None`` if
        nothing in the registry handles its type."""
        if x is None:
            return None
        klass = type(x)
        # Direct class hit first, then walk the MRO.
        if klass in self:
            return self[klass]
        for base in klass.__mro__:
            if base in self:
                return self[base]
        # Numpy array of objects? Inspect first element.
        if hasattr(x, '__iter__') and not isinstance(x, (str, bytes)):
            try:
                first = next(iter(x))
                if type(first) in self:
                    return self[type(first)]
            except StopIteration:
                pass
        return None


# Replace the bare ``dict`` with the typed registry so callers that import
# ``units.registry`` get the get_converter method.
registry = Registry(registry)
